  KEY `fk_card_bonuses_stat_source` (`stat_source_id`),
  KEY `idx_card_bonuses_state` (`state_id`),
  KEY `idx_card_bonuses_card_sort` (`card_id`,`sort_order`,`id`),
  CONSTRAINT `fk_card_bonus_card` FOREIGN KEY (`card_id`) REFERENCES `cards` (`id`) ON DELETE CASCADE,
