  `is_set_main` tinyint(1) NOT NULL DEFAULT '0',
  `state_id` int unsigned DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_cards_name` (`name`),
  KEY `idx_cards_type` (`card_type_id`),
  KEY `idx_cards_set` (`set_id`),
  KEY `idx_cards_state` (`state_id`),
  KEY `idx_cards_sort` (`sort_order`,`id`),
  CONSTRAINT `fk_cards_set` FOREIGN KEY (`set_id`) REFERENCES `card_sets` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_cards_state` FOREIGN KEY (`state_id`) REFERENCES `states` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cards_type` FOREIGN KEY (`card_type_id`) REFERENCES `card_types` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_cards_main_requires_set` CHECK (((`set_id` is not null) or (`is_set_main` = 0)))
) ENGINE=InnoDB AUTO_INCREMENT=261 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
