DROP TABLE IF EXISTS `item_bonuses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `item_bonuses` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `item_id` int unsigned NOT NULL,
  `stat_id` smallint unsigned NOT NULL,
  `value` decimal(10,2) NOT NULL COMMENT 'Может быть положительным или отрицательным',
  `value_type` enum('flat','percent') COLLATE utf8mb4_unicode_ci NOT NULL,
  `feature_id` int unsigned DEFAULT NULL,
  `text_note_id` int unsigned DEFAULT NULL,
  `state_id` int unsigned DEFAULT NULL,
  `scaling_type` enum('none','per_level','per_level_above','once_above','per_every_n_levels','per_stat','stat_threshold') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `scaling_step` int unsigned NOT NULL DEFAULT '1',
  `scaling_threshold` int unsigned NOT NULL DEFAULT '0',
  `item_type_condition_mode` enum('all','any') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all',
  `stat_source_id` smallint unsigned DEFAULT NULL,
  `stat_step` int unsigned DEFAULT NULL,
  `stat_threshold` int unsigned DEFAULT NULL,
  `stat_value_true` decimal(10,2) DEFAULT NULL,
  `feature_key` int unsigned NOT NULL DEFAULT '0',
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_item_bonus` (`item_id`,`stat_id`,`value_type`,(coalesce(`feature_id`,0)),(coalesce(`state_id`,0))),
  KEY `idx_item_bonuses_stat` (`stat_id`),
  KEY `idx_item_bonuses_feature` (`feature_id`),
  KEY `fk_item_bonuses_text_note` (`text_note_id`),
  KEY `fk_item_bonuses_stat_source` (`stat_source_id`),
  KEY `idx_item_bonuses_state` (`state_id`),
  KEY `idx_item_bonuses_item_sort` (`item_id`,`sort_order`,`id`),
  CONSTRAINT `fk_item_bonuses_feature` FOREIGN KEY (`feature_id`) REFERENCES `features` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_item_bonuses_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_item_bonuses_stat` FOREIGN KEY (`stat_id`) REFERENCES `stats` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_item_bonuses_stat_source` FOREIGN KEY (`stat_source_id`) REFERENCES `stats` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_item_bonuses_state` FOREIGN KEY (`state_id`) REFERENCES `states` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_item_bonuses_text_note` FOREIGN KEY (`text_note_id`) REFERENCES `text_notes` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2450 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
