DROP TABLE IF EXISTS `items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `items` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'Текстовая характеристика предмета, не влияет на параметры',
  `description_feature_id` int unsigned DEFAULT NULL,
  `icon_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_type_id` int unsigned NOT NULL,
  `grade` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `required_level` tinyint unsigned DEFAULT NULL,
  `internal_level` smallint unsigned DEFAULT NULL,
  `gender` enum('any','male','female') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'any',
  `base_defense` int unsigned NOT NULL DEFAULT '0',
  `base_attack` int unsigned NOT NULL DEFAULT '0',
  `base_attack_speed` decimal(8,2) NOT NULL DEFAULT '0.00',
  `base_dps` decimal(10,2) NOT NULL DEFAULT '0.00',
  `sockets` tinyint unsigned NOT NULL DEFAULT '0',
  `can_upgrade` tinyint(1) NOT NULL DEFAULT '0',
  `state_id` int unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_items_name` (`name`),
  KEY `idx_items_grade` (`grade`),
  KEY `idx_items_required_level` (`required_level`),
  KEY `idx_items_gender` (`gender`),
  KEY `idx_items_type` (`item_type_id`),
  KEY `idx_items_grade_level` (`grade`,`required_level`),
  KEY `idx_items_description_feature` (`description_feature_id`),
  KEY `idx_items_state` (`state_id`),
  KEY `idx_items_type_level` (`item_type_id`,`required_level`),
  CONSTRAINT `fk_items_description_feature` FOREIGN KEY (`description_feature_id`) REFERENCES `features` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_items_grade` FOREIGN KEY (`grade`) REFERENCES `grades` (`code`) ON DELETE RESTRICT,
  CONSTRAINT `fk_items_state` FOREIGN KEY (`state_id`) REFERENCES `states` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_items_type` FOREIGN KEY (`item_type_id`) REFERENCES `item_types` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_items_required_level` CHECK ((`required_level` between 1 and 65)),
  CONSTRAINT `chk_items_sockets` CHECK ((`sockets` between 0 and 3))
) ENGINE=InnoDB AUTO_INCREMENT=930 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

